/**
 * VIDEO 658 — the owner's four rules after watching it (14 October):
 *
 *   1. a picture generated by AI for a sentence is ALWAYS in the film — it was made for it;
 *   2. no slow motion: 658 played nearly every shot at 0.5–0.8× to stretch a 4 s source over a
 *      6–8 s sentence;
 *   3. no repetition: another picture that belongs there goes behind the shot instead —
 *      first another moment of the same YouTube video, then a generic library clip, and only when
 *      there is neither does the last frame hold (with a camera move);
 *   4. a photograph is never cut into two pieces (658 showed "The James" photo twice in a row).
 */
import fs from "fs";
import os from "os";
import path from "path";
import { describe, expect, it } from "vitest";

import { beatRelevanceBeatKey, composeBarrierAllows, createBeatRelevanceLedger, keepGeneratedForBeat, type BeatVisualContext } from "./beatVisualRelevance";
import { limitLongShots, MIN_PIECE_SPEED, MIN_STRETCH_SPEED } from "./longShotLimit";
import type { TimelineVideoClip } from "./projectTimeline";
import { MIN_FIT_SPEED, speedThatFitsSource } from "./timelineRenderer";
import { planYoutubePieces, YOUTUBE_MIN_PIECE_SPEED } from "./youtubeShotLimit";
import {
  __keepGeneratedForSentence,
  coverRestOfSentences,
  COVER_REST_MIN_SEC,
  ownArchiveFillAsk,
  sameVideoNeighbours,
  type CoverRestIo,
} from "./videoPipeline";

const SRC = (s: string) => fs.readFileSync(path.join(__dirname, s), "utf8");

function refuse(ledger: ReturnType<typeof createBeatRelevanceLedger>, clipPath: string, c: BeatVisualContext): void {
  const entry = {
    ctx: c,
    decision: {
      verdict: "does_not_fit",
      allowed: false,
      reprieved: false,
      cached: false,
      depicts: "A coral reef with fish.",
      reason: "The frames show a reef, not NASA's decision.",
    },
  } as never;
  ledger.byBeat.set(beatRelevanceBeatKey(c.sceneIndex, c.beatIndex, "path", clipPath), entry);
  ledger.byClipPath.set(clipPath, entry);
}

const okChecks = { valid: async () => true, durationSec: async () => 4, black: async () => false };

function clip(over: Partial<TimelineVideoClip> & { id: string; timelineStart: number; timelineEnd: number }): TimelineVideoClip {
  return {
    kind: "video",
    source: { provider: "internet_archive", providerAssetId: over.id },
    motion: "none",
    transitionIn: "hard_cut",
    transitionOut: "hard_cut",
    previewSource: "asset",
    ...over,
  } as TimelineVideoClip;
}

describe("1. an AI picture made for a sentence is always used", () => {
  it("a refusal on the record is overruled, and the compose barrier then lets it through", () => {
    const ledger = createBeatRelevanceLedger();
    const ai = "/w/scene_2_genimg_b0__pid_stability-d6ef5455e0942a93.mp4";
    refuse(ledger, ai, { sceneIndex: 2, beatIndex: 0, beatText: "If NASA had prioritized the ocean …" });
    expect(composeBarrierAllows(ledger, ai, undefined, { sceneIndex: 2, beatIndex: 0 }).allow).toBe(false);
    expect(keepGeneratedForBeat(ledger, ai, 2, 0)).toBe(1);
    expect(composeBarrierAllows(ledger, ai, undefined, { sceneIndex: 2, beatIndex: 0 }).allow).toBe(true);
    /** idempotent: nothing left to overrule */
    expect(keepGeneratedForBeat(ledger, ai, 2, 0)).toBe(0);
  });

  it("658's case — nobody looked — is placed anyway, and counted as on screen", async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "v658-ai-"));
    const ai = path.join(dir, "scene_1_genvid_b2__pid_elevenlabs_video-0178893c1062c39e.mp4");
    fs.writeFileSync(ai, "x");
    const dedup = { beatRelevance: createBeatRelevanceLedger(), usedContentKeys: new Set<string>(), refusedAssetsThisRender: new Set<string>() };
    const kept = await __keepGeneratedForSentence(dedup as never, 1, 2, ai, "GENERATED_VIDEO_FALLBACK", okChecks);
    expect(kept).toBe(ai);
    expect(dedup.usedContentKeys.size).toBe(1);
  });

  it("only the file can stop it: a black or unreadable generation is not placed", async () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "v658-ai-"));
    const ai = path.join(dir, "scene_2_genimg_b0__pid_stability-d6ef5455e0942a93.mp4");
    fs.writeFileSync(ai, "x");
    const dedup = { beatRelevance: createBeatRelevanceLedger(), usedContentKeys: new Set<string>(), refusedAssetsThisRender: new Set<string>() };
    expect(await __keepGeneratedForSentence(dedup as never, 2, 0, ai, "GENERATED_IMAGE_FALLBACK", { ...okChecks, black: async () => true })).toBeNull();
    expect(await __keepGeneratedForSentence(dedup as never, 2, 0, ai, "GENERATED_IMAGE_FALLBACK", { ...okChecks, valid: async () => false })).toBeNull();
  });

  it("every generated route keeps its picture instead of throwing it away; generation no longer waits for an approver", () => {
    const pipe = SRC("videoPipeline.ts");
    expect(pipe).not.toContain("generated, but not approved for the sentence — not used");
    expect(pipe.match(/return keepGeneratedForSentence\(dedup, scene\.index, beat\.index, outPath, /g)?.length).toBe(3);
    const gen = pipe.slice(pipe.indexOf("export async function generateMissingBeatImages("), pipe.indexOf("export const UNJUDGED_FOOTAGE_FALLBACK"));
    expect(gen).not.toContain("beatShortlistExhausted(");
    expect(gen).not.toContain("pictureEditorUnavailableReason(");
  });
});

describe("2. no slow motion anywhere", () => {
  it("every floor is normal speed", () => {
    expect(MIN_FIT_SPEED).toBe(1);
    expect(MIN_STRETCH_SPEED).toBe(1);
    expect(MIN_PIECE_SPEED).toBe(1);
    expect(YOUTUBE_MIN_PIECE_SPEED).toBe(1);
    expect(SRC("noRepeatedFootage.ts")).toMatch(/const SLOWEST = 1;/);
  });

  it("the renderer never slows a file shorter than its slot (658: 4.00 s file under 6.38 s)", () => {
    expect(speedThatFitsSource({ kind: "video", sourceIn: 0 }, 4, 6.38)).toBeNull();
  });

  it("658's vc_f41f3a10fa (4.79 s over 4.00 s of source): normal speed, then its last frame holds", () => {
    const { clips } = limitLongShots({
      clips: [clip({ id: "vc_f41f3a10fa", timelineStart: 6.38, timelineEnd: 11.17, sourceIn: 0, sourceOut: 4 })],
    });
    expect(clips).toHaveLength(1);
    expect(clips[0]!.speed ?? 1).toBe(1);
    expect(clips[0]!.holdAtSourceOut).toBe(true);
    expect(clips[0]!.camera).toBeDefined();
  });

  it("658's vc_69b499085c (7.27 s over 4.00 s): pieces at normal speed, never one slowed", () => {
    const { clips } = limitLongShots({
      clips: [clip({ id: "vc_69b499085c", timelineStart: 17.07, timelineEnd: 24.34, sourceIn: 0, sourceOut: 4 })],
    });
    expect(clips.length).toBeGreaterThan(1);
    for (const c of clips) expect(c.speed ?? 1).toBeGreaterThanOrEqual(1);
  });

  it("a YouTube piece without footage of its own holds the last frame, never slows", () => {
    const { pieces } = planYoutubePieces({
      inSec: 0,
      durationSec: 8.32,
      facts: { sourceDurationSec: 2.77, cutsSec: [], measured: true },
      slowRatherThanRepeat: true,
    });
    for (const p of pieces) expect(p.speed ?? 1).toBe(1);
    expect(pieces.some((p) => p.hold)).toBe(true);
  });
});

describe("4. a photograph is never cut into pieces", () => {
  it("658's vc_a8072b0a0a (a 7.26 s photo over a 4 s file): one shot, normal speed, held, moving", () => {
    const { clips, notes } = limitLongShots({
      clips: [clip({ id: "vc_a8072b0a0a", still: true, timelineStart: 35.44, timelineEnd: 42.7, sourceIn: 0, sourceOut: 4 })],
    });
    expect(clips).toHaveLength(1);
    expect(clips[0]!.id).toBe("vc_a8072b0a0a");
    expect(clips[0]!.timelineEnd - clips[0]!.timelineStart).toBeCloseTo(7.26, 2);
    expect(clips[0]!.speed ?? 1).toBe(1);
    expect(clips[0]!.holdAtSourceOut).toBe(true);
    expect(clips[0]!.camera).toBeDefined();
    expect(notes.join(" ")).toContain("never cut into pieces");
  });

  it("the same footage of 7.26 s IS still cut (the six-second rule stands for moving pictures)", () => {
    const { clips } = limitLongShots({
      clips: [clip({ id: "vc_moving", timelineStart: 0, timelineEnd: 7.26, sourceIn: 0, sourceOut: 20 })],
    });
    expect(clips.length).toBe(2);
  });

  it("the translator marks a photograph on the timeline clip", () => {
    expect(SRC("edlToTimeline.ts")).toContain("...(isStill ? { still: true } : {}),");
  });
});

describe("3. the rest of a sentence gets another picture behind its shot", () => {
  const OWN = "/w/scene_0_ytfu_0m1_t1000d40__pid_youtube_cc-aaaaaaaaaaaaaaaa.mp4";
  const NEXT = "/w/scene_0_ytfu_0m2_t1040d38__pid_youtube_cc-aaaaaaaaaaaaaaaa.mp4";
  const FAR = "/w/scene_0_ytfu_0m4_t1500d40__pid_youtube_cc-aaaaaaaaaaaaaaaa.mp4";
  const OTHER_VIDEO = "/w/scene_0_ytfu_0m1_t1040d40__pid_youtube_cc-bbbbbbbbbbbbbbbb.mp4";

  it("sameVideoNeighbours: only the same video, nearest first, never the shot itself", () => {
    expect(sameVideoNeighbours([OWN], [FAR, OTHER_VIDEO, OWN, NEXT])).toEqual([NEXT, FAR]);
    expect(sameVideoNeighbours(["/w/scene_0_b0_curated_a58618.mp4"], [NEXT])).toEqual([]);
    /** the transformed copy of the placed shot is the same shot */
    expect(sameVideoNeighbours([OWN.replace(".mp4", "_transformed.mp4")], [OWN, NEXT])).toEqual([NEXT]);
  });

  function fixture(handed: string[], refused: string[] = []) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "v658-rest-"));
    const real = (p: string) => {
      const f = path.join(dir, path.basename(p));
      fs.writeFileSync(f, "x");
      return f;
    };
    const own = real(OWN);
    const files = handed.map(real);
    const ledger = createBeatRelevanceLedger();
    for (const r of refused) refuse(ledger, path.join(dir, path.basename(r)), { sceneIndex: 0, beatIndex: 1, beatText: "x" });
    const beat = { index: 1, text: "This neglected voyage could've reshaped our understanding.", holdSec: 7.27 };
    const vr = { clips: [own], beatDurations: [4], clipBeatIndices: [1], beats: [beat] };
    const dedup = {
      sceneBeatsBySceneIndex: new Map([[0, [beat]]]),
      beatCandidateCalls: new Map([["0:1", [{ paths: [own, ...files], beatText: beat.text, sourceQuery: "", opts: {} }]]]),
      beatRelevance: ledger,
      usedPaths: new Set<string>(),
      usedContentKeys: new Set<string>(),
      usedCuratedAssetIds: new Set<number>(),
      usedCuratedStorageUrls: new Set<string>(),
      refusedAssetsThisRender: new Set<string>(),
    };
    return { dir, vr, dedup, files };
  }

  const noGeneric: CoverRestIo = { checks: okChecks, genericClip: async () => null };

  it("658's s1b0 (7.27 s, one 4 s shot): another moment of the same video goes behind it", async () => {
    const { vr, dedup, files } = fixture([OTHER_VIDEO, NEXT]);
    const t = await coverRestOfSentences([{ index: 0, text: "" } as never], [vr as never], dedup as never, "/tmp", noGeneric);
    expect(t.sameVideo).toBe(1);
    expect(vr.clips[1]).toBe(files[1]);
    expect(vr.clipBeatIndices[1]).toBe(1);
    expect(vr.beatDurations[1]).toBeCloseTo(3.27, 2);
  });

  it("a moment the picture editor refused is not taken; the generic library is next", async () => {
    const { vr, dedup } = fixture([NEXT], [NEXT]);
    const generic: CoverRestIo = {
      checks: okChecks,
      genericClip: async (_s, _b, needed) => ({ path: "/w/scene_0_generic_rest_b1_1__pid_generic_footage-cccccccccccccccc.mp4", durationSec: Math.max(needed, 6) }),
    };
    const t = await coverRestOfSentences([{ index: 0, text: "" } as never], [vr as never], dedup as never, "/tmp", generic);
    expect(t).toEqual({ sameVideo: 0, generic: 1, held: 0 });
    expect(vr.clips[1]).toContain("generic_rest");
  });

  it("with nothing at all, nothing is invented: the shot holds its last frame and that is said", async () => {
    const { vr, dedup } = fixture([]);
    const t = await coverRestOfSentences([{ index: 0, text: "" } as never], [vr as never], dedup as never, "/tmp", noGeneric);
    expect(t).toEqual({ sameVideo: 0, generic: 0, held: 1 });
    expect(vr.clips).toHaveLength(1);
  });

  it("a sentence its shots already cover, or less than a second short, is left alone", async () => {
    const { vr, dedup } = fixture([NEXT]);
    vr.beatDurations[0] = 7.27 - (COVER_REST_MIN_SEC - 0.1);
    const t = await coverRestOfSentences([{ index: 0, text: "" } as never], [vr as never], dedup as never, "/tmp", noGeneric);
    expect(t).toEqual({ sameVideo: 0, generic: 0, held: 0 });
    expect(vr.clips).toHaveLength(1);
  });

  it("it runs after every other fallback, before the film is assembled", () => {
    const pipe = SRC("videoPipeline.ts");
    const generic = pipe.indexOf("await placeGenericMovingFallbacks(scenes, sceneVisualResults, visualDedup, workDir);");
    const rest = pipe.indexOf("await coverRestOfSentences(scenes, sceneVisualResults, visualDedup, workDir);");
    expect(generic).toBeGreaterThan(-1);
    expect(rest).toBeGreaterThan(generic);
  });
});

describe("5. the own archive is asked with the sentence's own words too — for every topic alike", () => {
  const beat = (text: string, searchQuery?: string, keywords?: string[]) =>
    ({ index: 0, text, holdSec: 6, ...(searchQuery ? { searchQuery } : {}), ...(keywords ? { keywords } : {}) }) as never;

  it("658: 'NASA' is added to the ocean question, not put in its place", () => {
    const asked = ownArchiveFillAsk(beat("In the 1960s, NASA was leading ocean exploration.", "ocean exploration 1960s", ["ocean", "research vessel"]), "NASA");
    expect(asked.searchQuery).toBe("NASA ocean exploration 1960s");
    expect(asked.keywords).toEqual(["ocean", "research vessel", "NASA"]);
  });

  it.each([
    ["Tesla", "Gigafactory assembly line robots", ["factory", "robots"]],
    ["Roman Empire", "legionaries marching", ["soldiers"]],
    ["Taylor Swift", "stadium crowd at night", ["concert"]],
  ])("the same rule for %s", (subject, query, keywords) => {
    const asked = ownArchiveFillAsk(beat("A sentence.", query, keywords), subject);
    expect(asked.searchQuery).toBe(`${subject} ${query}`);
    expect(asked.keywords).toEqual([...keywords, subject]);
  });

  it("a query that already names the subject is kept as it is; a sentence without a query asks on the subject", () => {
    expect(ownArchiveFillAsk(beat("x", "NASA budget cuts 1970s"), "NASA").searchQuery).toBe("NASA budget cuts 1970s");
    expect(ownArchiveFillAsk(beat("x"), "NASA").searchQuery).toBe("NASA");
  });

  it("the fill uses it; the old ask that dropped the sentence's words is gone", () => {
    const pipe = SRC("videoPipeline.ts");
    expect(pipe).toContain("const asked: SceneBeat = subject ? ownArchiveFillAsk(f.beat, subject) : f.beat;");
    expect(pipe).not.toContain("searchQuery: subject, powerWord: subject, keywords: [subject], visualDescription: undefined");
  });
});
